using System.Collections.Generic;public class Solution{public int LadderLength(string b,string e,IList<string>wl){var d=new HashSet<string>(wl);if(!d.Contains(e))return 0;var q=new Queue<(string,int)>();q.Enqueue((b,1));d.Remove(b);while(q.Count>0){var (w,s)=q.Dequeue();if(w==e)return s;var a=w.ToCharArray();for(int i=0;i<a.Length;i++){char old=a[i];for(char c='a';c<='z';c++){a[i]=c;var x=new string(a);if(d.Remove(x))q.Enqueue((x,s+1));}a[i]=old;}}return 0;}}
